package com.clavis.reader;
import java.io.*;import java.nio.*;import java.nio.channels.*;import java.nio.charset.*;import java.util.*;
/** Chapter text samples referenced by a QuickTime chap track reference. */
final class QuickTimeChapters {
 static final int LIMIT=100000;
 static final class Atom{String type;long body,end;Atom(String t,long b,long e){type=t;body=b;end=e;}}
 static List<Atom> children(FileChannel c,long from,long end)throws IOException{ArrayList<Atom> out=new ArrayList<>();for(long p=from;p+8<=end&&out.size()<LIMIT;){byte[] h=EmbeddedChapters.read(c,p,8);long n=EmbeddedChapters.u32(h,0);int head=8;if(n==1){if(end-p<16)break;n=ByteBuffer.wrap(EmbeddedChapters.read(c,p+8,8)).getLong();head=16;}if(n==0)n=end-p;if(n<head||n>end-p)break;out.add(new Atom(new String(h,4,4,StandardCharsets.ISO_8859_1),p+head,p+n));p+=n;}return out;}
 static Atom child(FileChannel c,Atom parent,String type)throws IOException{if(parent==null)return null;for(Atom a:children(c,parent.body,parent.end))if(a.type.equals(type))return a;return null;}
 static byte[] data(FileChannel c,Atom a)throws IOException{if(a==null)throw new IOException("Missing chapter sample table");return EmbeddedChapters.read(c,a.body,(int)Math.min(a.end-a.body,4*1024*1024));}
 static int count(byte[] b,int at,int width)throws IOException{if(b.length<at+4)throw new IOException("Truncated chapter table");long n=EmbeddedChapters.u32(b,at);if(n>LIMIT||n>(b.length-at-4)/width)throw new IOException("Invalid chapter table");return (int)n;}
 static List<EmbeddedChapters.Marker> read(FileChannel c)throws IOException{ArrayList<EmbeddedChapters.Marker> out=new ArrayList<>();Atom root=new Atom("root",0,c.size()),moov=child(c,root,"moov");if(moov==null)return out;List<Atom> tracks=new ArrayList<>();Set<Long> ids=new HashSet<>();for(Atom t:children(c,moov.body,moov.end))if(t.type.equals("trak")){tracks.add(t);Atom chap=child(c,child(c,t,"tref"),"chap");if(chap!=null){byte[] b=data(c,chap);for(int p=0;p+4<=b.length;p+=4)ids.add(EmbeddedChapters.u32(b,p));}}
 for(Atom t:tracks){Atom tkhd=child(c,t,"tkhd");if(tkhd==null)continue;byte[] h=data(c,tkhd);int idOffset=h.length>0&&h[0]==1?20:12;if(h.length<idOffset+4||!ids.contains(EmbeddedChapters.u32(h,idOffset)))continue;Atom mdia=child(c,t,"mdia"),stbl=child(c,child(c,mdia,"minf"),"stbl");if(stbl==null)continue;byte[] mdhd=data(c,child(c,mdia,"mdhd"));int scaleOffset=mdhd.length>0&&mdhd[0]==1?20:12;if(mdhd.length<scaleOffset+4)continue;long scale=EmbeddedChapters.u32(mdhd,scaleOffset);if(scale==0)continue;
 byte[] sizes=data(c,child(c,stbl,"stsz"));if(sizes.length<12)continue;long fixed=EmbeddedChapters.u32(sizes,4),samples=EmbeddedChapters.u32(sizes,8);if(samples>LIMIT||samples==0||fixed==0&&samples>(sizes.length-12)/4)continue;int n=(int)samples;long[] times=new long[n],offsets;byte[] ts=data(c,child(c,stbl,"stts"));int entries=count(ts,4,8),sample=0;long time=0;for(int j=0;j<entries&&sample<n;j++){long run=EmbeddedChapters.u32(ts,8+j*8),delta=EmbeddedChapters.u32(ts,12+j*8);for(long k=0;k<run&&sample<n;k++){times[sample++]=time*1000/scale;time+=delta;}}if(sample!=n)continue;
 Atom co=child(c,stbl,"stco");boolean wide=false;if(co==null){co=child(c,stbl,"co64");wide=true;}byte[] chunks=data(c,co);int nc=count(chunks,4,wide?8:4);offsets=new long[nc];for(int j=0;j<nc;j++)offsets[j]=wide?ByteBuffer.wrap(chunks,8+j*8,8).getLong():EmbeddedChapters.u32(chunks,8+j*4);
 byte[] sc=data(c,child(c,stbl,"stsc"));int nr=count(sc,4,12),rule=0;sample=0;for(int chunk=1;chunk<=nc&&sample<n;chunk++){while(rule+1<nr&&EmbeddedChapters.u32(sc,8+(rule+1)*12)<=chunk)rule++;if(nr==0||EmbeddedChapters.u32(sc,8+rule*12)>chunk)break;long per=EmbeddedChapters.u32(sc,12+rule*12),pos=offsets[chunk-1];for(long j=0;j<per&&sample<n;j++,sample++){long len=fixed>0?fixed:EmbeddedChapters.u32(sizes,12+sample*4);if(pos<0||len<2||len>1024*1024||pos>c.size()-len)throw new IOException("Invalid chapter text sample");byte[] text=EmbeddedChapters.read(c,pos,(int)len);int bytes=(text[0]&255)*256+(text[1]&255);if(bytes<=text.length-2){Charset charset=bytes>=2&&((text[2]&255)==254&&(text[3]&255)==255||(text[2]&255)==255&&(text[3]&255)==254)?StandardCharsets.UTF_16:StandardCharsets.UTF_8;String label=new String(text,2,bytes,charset).trim();if(!label.isEmpty())out.add(new EmbeddedChapters.Marker(times[sample],label));}pos+=len;}}
 if(!out.isEmpty())break;}
 return out;}
}
